// Fuzz/property corpus and boundaries (audit CP-10).
//
// - UNPI: fixed-seed malformed corpus generated by the pinned Node oracle
//   (`tools/oracle/fuzz-corpus.mjs` -> fixtures/fuzz_unpi.json); accept/reject
//   and parsed fields must match upstream.
// - Buffalo: deterministic property round-trips (write -> read) and truncated
//   reads must either return or panic with a Node-style range error, never hang.
// - ZCL: random buffers must be rejected or round-trip through `to_buffer`.

use std::panic::{catch_unwind, AssertUnwindSafe};

use serde::Deserialize;

use zigbee_apiarist::adapter::z_stack::unpi::frame::Frame;
use zigbee_apiarist::buffalo::buffalo::Buffalo;

#[derive(Debug, Deserialize)]
struct UnpiCase {
    id: String,
    buffer: String,
    length: u8,
    #[serde(rename = "fcsPosition")]
    fcs_position: usize,
    ok: bool,
    r#type: Option<u8>,
    subsystem: Option<u8>,
    #[serde(rename = "commandID")]
    command_id: Option<u8>,
    data: Option<String>,
}

fn unhex(value: &str) -> Vec<u8> {
    (0..value.len())
        .step_by(2)
        .map(|index| u8::from_str_radix(&value[index..index + 2], 16).expect("hex"))
        .collect()
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

#[test]
fn unpi_malformed_corpus_matches_upstream() {
    let cases: Vec<UnpiCase> =
        serde_json::from_str(include_str!("fixtures/fuzz_unpi.json")).expect("fuzz corpus");
    assert!(cases.len() >= 100, "corpus too small");
    let mut accepted = 0;

    for case in cases {
        let buffer = unhex(&case.buffer);
        let frame = catch_unwind(AssertUnwindSafe(|| {
            Frame::from_buffer(case.length, case.fcs_position, &buffer)
        }))
        .unwrap_or_else(|_| panic!("{}: parser panicked instead of rejecting", case.id));

        match (frame, case.ok) {
            (Some(frame), true) => {
                accepted += 1;
                assert_eq!(
                    frame.r#type as u8,
                    case.r#type.expect("type"),
                    "{}",
                    case.id
                );
                assert_eq!(
                    frame.subsystem as u8,
                    case.subsystem.expect("subsystem"),
                    "{}",
                    case.id
                );
                assert_eq!(
                    frame.commandID,
                    case.command_id.expect("command"),
                    "{}",
                    case.id
                );
                assert_eq!(
                    frame.data,
                    unhex(case.data.as_deref().unwrap_or("")),
                    "{}",
                    case.id
                );
            }
            (None, false) => {}
            (frame, ok) => panic!("{}: upstream ok={ok}, rust={frame:?}", case.id),
        }
    }
    assert!(accepted > 0, "corpus had no accepted frames");
}

/// Deterministic LCG so the property run is reproducible without a fuzz crate.
struct Lcg(u64);

impl Lcg {
    fn next(&mut self) -> u64 {
        self.0 = self
            .0
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        self.0
    }

    fn bytes(&mut self, length: usize) -> Vec<u8> {
        (0..length).map(|_| self.next() as u8).collect()
    }
}

#[test]
fn buffalo_round_trip_property_and_truncated_reads() {
    let mut rng = Lcg(0x5eed_1234);
    for _ in 0..500 {
        let length = 1 + (rng.next() % 8) as usize;
        let value = rng.next();
        let mut writer = Buffalo::new(vec![0; 32], 0);
        writer.write_uint32(u64::from(value as u32));
        let encoded = writer.get_written();
        let mut reader = Buffalo::new(encoded, 0);
        assert_eq!(reader.read_uint32(), u64::from(value as u32));
        assert_eq!(reader.get_position(), 4);

        let random = rng.bytes(length);
        let mut buffalo = Buffalo::new(random.clone(), 0);
        let result = catch_unwind(AssertUnwindSafe(|| buffalo.read_uint32()));
        // Either the full value is present or the Node-style range check fires.
        assert!(result.is_ok() || random.len() < 4);
    }
}

#[test]
fn zcl_random_buffers_are_rejected_or_round_trip() {
    let mut rng = Lcg(0xfeed_9876);
    for _ in 0..500 {
        let length = (rng.next() % 24) as usize;
        let buffer = rng.bytes(length);
        let cluster_id = [6u16, 8, 0x0402][(rng.next() % 3) as usize];
        let header = zigbee_apiarist::zspec::zcl::zcl_header::Header::new(
            zigbee_apiarist::zspec::zcl::zcl_header::FrameControl {
                reserved_bits: (rng.next() % 8) as u8,
                frame_type: zigbee_apiarist::zspec::zcl::zcl_header::FrameType::GLOBAL,
                direction: if rng.next() % 2 == 0 {
                    zigbee_apiarist::zspec::zcl::zcl_header::Direction::CLIENT_TO_SERVER
                } else {
                    zigbee_apiarist::zspec::zcl::zcl_header::Direction::SERVER_TO_CLIENT
                },
                disable_default_response: rng.next() % 2 == 0,
                manufacturer_specific: false,
            },
            None,
            rng.next() as u8,
            rng.next() as u8,
        );
        let result = catch_unwind(AssertUnwindSafe(|| {
            zigbee_apiarist::zspec::zcl::zcl_frame::Frame::from_buffer(
                cluster_id,
                Some(header),
                &buffer,
                &Default::default(),
            )
        }));
        if let Ok(frame) = result {
            let serialized = catch_unwind(AssertUnwindSafe(|| frame.to_buffer()));
            let Ok(serialized) = serialized else {
                continue;
            };
            let reparsed = catch_unwind(AssertUnwindSafe(|| {
                zigbee_apiarist::zspec::zcl::zcl_frame::Frame::from_buffer(
                    cluster_id,
                    Some(frame.header.clone()),
                    &serialized,
                    &Default::default(),
                )
            }));
            if let Ok(reparsed) = reparsed {
                assert_eq!(reparsed.to_buffer(), serialized);
            }
        }
    }
}
